func ScanBannedRegister(text string) []RegisterViolation // unions ScanDefineByNegation, sorts ASCENDING BY OFFSET so hits[0].At is usable as protectFrom

func RepairOrderingRegisterAction(ctx, params) (interface{}, error)
  scan each item[text_key] with datahelpers.ScanBannedRegister -> []registerTarget{ProtectFrom: hits[0].At}
  if none: return object with record_key = [] (EMPTY ARRAY — write_site_spec deep-merges; omitting it leaves the previous run's record accusing a clean artefact for ever)
  logger.Warn BEFORE repairing — the producer's error rate, emitted whether or not the repair then succeeds
  one LLM call for all targets; LogLLMCall with __sent_max_tokens as the ceiling of record; truncation classified three ways
  judge each; reconcile every unanswered target so len(records) == len(targets) always
  return object with items patched and record_key = records

func judgeRegisterRewrite(t registerTarget, to string, floorPct int) (bool, string) {
  1. datahelpers.AcceptNegationRewrite(t.Text, to, t.ProtectFrom) // shared structural judge — shapes, displacement, protected figures/links, invented names
  2. if hits := datahelpers.ScanBannedRegister(to); len(hits) > 0 -> "still_"+kind+"_"+name // layer 1 re-scans SHAPES ONLY; without this the arms displace into each other
  3. if t.Differentiated && len(to)*100 < len(t.Text)*floorPct -> differentiation_stripped // 60%, this lane's ACK rule
  4. if t.Differentiated && isTruncationOf(t.Text, to) -> truncation_only // EXACT, not heuristic: on a differentiated point the violating construction IS the comparison and the distinction is what it compares against, so ruling 7's truncate-before-the-comparison removes it every time, at any length. Undifferentiated points stay exempt: there truncation is sanctioned and demonstrably lossless.
}
